const types = new Map();
types.set("troll", Object.freeze({
  id: "troll", baseHealth: 48, attack: "The troll clubs you!",
}));

function spawn(id) {
  const type = types.get(id);
  if (!type) throw new Error(`unknown type ${id}`);   // fail fast
  return Object.create(type, { health: { value: type.baseHealth, writable: true } });
}

const troll = spawn("troll");   // troll.attack resolves through the prototype chain
